<?php require __DIR__.'/vendor/autoload.php'; $app = require_once __DIR__.'/bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); use Illuminate\Support\Facades\DB; echo '=== Branches ==='.PHP_EOL; foreach(DB::table('branches')->get() as $b) echo '  [{->id}] {->name} ({->code}) business_id={->business_id} status={->status}'.PHP_EOL; echo PHP_EOL.'=== Users (full) ==='.PHP_EOL; foreach(DB::table('users')->select('id','name','email','role_id','branch_id','business_id','status')->get() as $u) echo '  [{->id}] {->name} ({->email}) role_id='.var_export($u->role_id,true).' branch_id='.var_export($u->branch_id,true).' business_id='.var_export($u->business_id,true).PHP_EOL; echo PHP_EOL.'=== Cashier role permissions count ==='.PHP_EOL; $roleId = DB::table('roles')->where('slug','sales')->value('id'); echo '  Cashier role id: '.var_export($roleId,true).PHP_EOL; echo '  Has sales.create: '.var_export(DB::table('permission_role')->where('role_id',$roleId)->where('permission_id', DB::table('permissions')->where('name','sales.create')->value('id'))->exists(),true).PHP_EOL; 
